// Import of required libraries
import { test, expect, getBaseUrl, getValue, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { signIn, signOut, dismissProjectOwnerReminder, refreshWebhooksList } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8055");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(1273000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(`${baseUrl}/admin/login`);

    const response0 = await signIn(page, "admin@example.com", "admin");

    await page.goto(`${baseUrl}/admin/webhooks`);
    // Wait for network activities to finish
    await page.waitForTimeout(15000);

    await page.goto(`${baseUrl}/admin/login`);
    await signOut(page);

    const response1 = await signIn(page, "admin@example.com", "admin");

    expect(response1.status(), 'login response status').toBe(200);

    await dismissProjectOwnerReminder(page);
    await refreshWebhooksList(page);

    await expect(page, 'stays on the Webhooks module route after refresh').toHaveURL(`${baseUrl}/admin/webhooks`);
    await expect(page.getByRole("button", { name: "refresh" }), 'refresh control is usable again after the reload').toBeEnabled();
    await expect(page.locator(".webhooks-list"), 'webhook table renders its URL column').toContainText("URL");
});
